BEGIN;
ALTER TABLE calculation.run ADD COLUMN IF NOT EXISTS revision integer NOT NULL DEFAULT 1 CHECK(revision>0),ADD COLUMN IF NOT EXISTS supersedes_run_id uuid REFERENCES calculation.run(run_id),ADD COLUMN IF NOT EXISTS correction_reason text;
ALTER TABLE calculation.run DROP CONSTRAINT IF EXISTS run_pool_id_business_date_rules_version_key;
CREATE UNIQUE INDEX IF NOT EXISTS calculation_run_business_revision_unique ON calculation.run(pool_id,business_date,rules_version,revision);
CREATE TABLE IF NOT EXISTS calculation.run_step(run_id uuid NOT NULL REFERENCES calculation.run(run_id),step_name text NOT NULL CHECK(step_name~'^[A-Z][A-Z0-9_]{1,63}$'),input_checksum_sha256 text NOT NULL CHECK(input_checksum_sha256~'^[a-f0-9]{64}$'),output_checksum_sha256 text CHECK(output_checksum_sha256 IS NULL OR output_checksum_sha256~'^[a-f0-9]{64}$'),status text NOT NULL CHECK(status IN('RUNNING','COMPLETED','FAILED')),attempt_count integer NOT NULL DEFAULT 1 CHECK(attempt_count>0),started_at timestamptz NOT NULL DEFAULT clock_timestamp(),completed_at timestamptz,failure_message text,PRIMARY KEY(run_id,step_name),CHECK((status='COMPLETED' AND output_checksum_sha256 IS NOT NULL AND completed_at IS NOT NULL)OR status<>'COMPLETED'));
CREATE OR REPLACE FUNCTION calculation.guard_approved_run_mutation()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF TG_OP='DELETE' AND OLD.status IN('APPROVED','POSTED','ARCHIVED')THEN RAISE EXCEPTION 'Approved calculation run is immutable';END IF;IF TG_OP='UPDATE' AND OLD.status IN('APPROVED','POSTED','ARCHIVED')THEN IF(to_jsonb(NEW)-'status')IS DISTINCT FROM(to_jsonb(OLD)-'status')THEN RAISE EXCEPTION 'Approved calculation run content is immutable; create a correction run';END IF;IF NOT((OLD.status='APPROVED' AND NEW.status='POSTED')OR(OLD.status='POSTED' AND NEW.status='ARCHIVED')OR OLD.status=NEW.status)THEN RAISE EXCEPTION 'Invalid immutable calculation run transition';END IF;END IF;RETURN CASE WHEN TG_OP='DELETE'THEN OLD ELSE NEW END;END;$$;
DROP TRIGGER IF EXISTS approved_calculation_run_immutable ON calculation.run;CREATE TRIGGER approved_calculation_run_immutable BEFORE UPDATE OR DELETE ON calculation.run FOR EACH ROW EXECUTE FUNCTION calculation.guard_approved_run_mutation();
CREATE OR REPLACE FUNCTION calculation.guard_approved_allocation_mutation()RETURNS trigger LANGUAGE plpgsql AS $$DECLARE guarded_run_id uuid:=CASE WHEN TG_OP='INSERT'THEN NEW.run_id ELSE OLD.run_id END;BEGIN IF EXISTS(SELECT 1 FROM calculation.run WHERE run_id=guarded_run_id AND status IN('APPROVED','POSTED','ARCHIVED'))THEN RAISE EXCEPTION 'Approved calculation allocations are immutable';END IF;RETURN CASE WHEN TG_OP='DELETE'THEN OLD ELSE NEW END;END;$$;
DROP TRIGGER IF EXISTS approved_allocation_result_immutable ON calculation.allocation_result;CREATE TRIGGER approved_allocation_result_immutable BEFORE INSERT OR UPDATE OR DELETE ON calculation.allocation_result FOR EACH ROW EXECUTE FUNCTION calculation.guard_approved_allocation_mutation();
ALTER TABLE calculation.run ADD CONSTRAINT calculation_correction_reason_required CHECK((supersedes_run_id IS NULL AND correction_reason IS NULL)OR(supersedes_run_id IS NOT NULL AND length(trim(correction_reason))>0));
COMMIT;
